-- ============================================================
-- MIGRATION: Expand categories + 51 new activities seed data
-- File: supabase/migrations/003_expand_activities.sql
-- Run in Supabase SQL editor after 001_init.sql and 002_seed.sql
-- ============================================================

-- 1. Drop and recreate the CHECK constraint with new categories
ALTER TABLE activities DROP CONSTRAINT IF EXISTS activities_category_check;

ALTER TABLE activities ADD CONSTRAINT activities_category_check
  CHECK (category IN (
    'yacht', 'wine', 'horse', 'quad', 'surf', 'fishing', 'rope', 'excursion',
    'buggy', 'jeep', 'paraglide', 'sailing', 'skydive', 'kayak', 'diving',
    'farm', 'canyon', 'zipline', 'helicopter'
  ));


-- 2. Add new test partners
